/**
 * @name Code injection via eval/exec/compile
 * @description Detects use of eval, exec, or compile that may allow code injection
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection-attrs
 * @tags security
 *        external/cwe/cwe-094
 *        external/cwe/cwe-095
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters from functions
    source instanceof DataFlow::ParameterNode
    or
    // Attribute access that could be user-controlled
    exists(Attribute attr |
      source.asExpr() = attr
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin("eval").getACall() or
        call = API::builtin("exec").getACall() or
        call = API::builtin("compile").getACall()
      ) and
      sink = call.getArg(_)
    )
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;
import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where CodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential code injection from $@.", source.getNode(), "user-controlled source"

/**
 * @name Unsafe attribute access in attrs
 * @description Detects potentially unsafe use of getattr/setattr/delattr with user-controlled attribute names
 * @kind path-problem
 * @problem.severity warning
 * @id py/unsafe-attribute-access-attrs
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module UnsafeAttrConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Function parameters that could be user-controlled
    source instanceof DataFlow::ParameterNode
    or
    // Dictionary access that could contain user data
    exists(DataFlow::AttrRead attr |
      attr.getAttributeName() in ["name", "alias", "type", "default", "metadata"] and
      source.asExpr() = attr.asExpr()
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["getattr", "setattr", "delattr", "hasattr"] and
      sink = call.getArg(1)
      or
      call = API::builtin(["getattr", "setattr", "delattr", "hasattr"]).getACall() and
      sink = call.getArg(1)
    )
  }
}

module UnsafeAttrFlow = TaintTracking::Global<UnsafeAttrConfig>;
import UnsafeAttrFlow::PathGraph

from UnsafeAttrFlow::PathNode source, UnsafeAttrFlow::PathNode sink
where UnsafeAttrFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potentially unsafe attribute access from $@.", source.getNode(), "user-controlled source"
